void test_scene_put_verify_borrows_service_staging() {
  orbit::SceneDto dto{};
  dto.valid = true;
  dto.global_fields = orbit::SceneBpm;
  dto.globals.bpm = 100;
  char text[orbit::kSceneMaxBytes]{};
  std::size_t length = 0;
  {
    orbit::SceneSchemaResolver schema{nullptr, schema_lookup};
    CHECK(orbit::encode_scene(dto, schema, text, sizeof(text), length) == orbit::SceneResult::Ok);
  }
  std::uint8_t reason = 0;
  bool crc_ok = false;
  const auto* scene_text = reinterpret_cast<const std::uint8_t*>(text);
  {
    // A scene operation in progress owns the staging object: the verify is refused.
    Harness h;
    CHECK(h.service.request(orbit::SceneOperation::Save));
    std::uint8_t frame[orbit::kSceneMaxBytes + 64];
    const std::size_t n = build_frame('P', "Scene01", 7, scene_text, static_cast<std::uint32_t>(length), frame);
    h.feed(frame, n);
    CHECK(first_frame_type(h.out, reason, crc_ok) == 'N');
    CHECK(reason == static_cast<std::uint8_t>(NakReason::Busy));
    CHECK(!h.fs.cell({orbit::SceneFileKind::Scene, 0}).exists);
    CHECK(!h.fs.cell({orbit::SceneFileKind::SceneTemp, 0}).exists);
    CHECK(h.session.counters().busy == 1);
  }
  {
    // Idle service: the same PUT verifies through the shared staging and commits.
    Harness h;
    CHECK(h.service.lend_staging() != nullptr);
    std::uint8_t frame[orbit::kSceneMaxBytes + 64];
    const std::size_t n = build_frame('P', "Scene01", 7, scene_text, static_cast<std::uint32_t>(length), frame);
    h.feed(frame, n);
    CHECK(first_frame_type(h.out, reason, crc_ok) == 'A' && crc_ok);
    CHECK(h.fs.cell({orbit::SceneFileKind::Scene, 0}).exists);
    CHECK(!h.fs.cell({orbit::SceneFileKind::SceneTemp, 0}).exists);
    CHECK(h.service.lend_staging() != nullptr);
  }
}

int main() {
  test_crc_and_names();
  test_golden_put_commits_and_acks();
  test_bad_checksum_preserves_target();
  test_truncated_transfer_aborts_cleanly();
  test_oversize_is_discarded_without_writes();
  test_disallowed_names_refused_before_storage();
  test_busy_refused_while_running();
  test_storage_full_preserves_target();
  test_invalid_content_rejected();
  test_unknown_frame_type_is_framing_error();
  test_silent_short_write_is_never_acknowledged();
  test_gate_closing_mid_payload_discards_transfer();
  test_get_streams_file_with_valid_crc();
  test_get_missing_and_list();
  test_scene_put_verify_borrows_service_staging();
  test_scene_names_put_is_strict();
  test_committed_names_put_invalidates_loaded_names();
  if (failures != 0) {
    std::fprintf(stderr, "t13a_protocol: %d failure(s)\n", failures);
    return 1;
  }
  std::puts("t13a_protocol: all checks passed");
  return 0;
}
